{
  "root": "main_stack",
  "state": {
    "ingredients": [
      { "ingredient": "800g sweet potatoes (1cm cubes)" },
      { "ingredient": "800g canned chickpeas (drained)" },
      { "ingredient": "200g fresh spinach" },
      { "ingredient": "30ml olive oil" },
      { "ingredient": "10g smoked paprika" },
      { "ingredient": "5g garlic powder" },
      { "ingredient": "salt/pepper" }
    ],
    "instructions": [
      { "step": "Step 1", "instruction": "Heat olive oil in a large oven-safe skillet over medium-high heat. Add sweet potatoes and cook for 8-10 minutes until edges are browned." },
      { "step": "Step 2", "instruction": "Stir in drained chickpeas, paprika, and garlic powder. Transfer skillet to oven at 200°C for 15-20 minutes until potatoes are tender." },
      { "step": "Step 3", "instruction": "Return skillet to stovetop over low heat. Toss in fresh spinach and stir for 2 minutes until just wilted. Season with salt and pepper." }
    ],
    "nutrition": [
      { "nutrient": "Calories", "value": "410 kcal" },
      { "nutrient": "Protein", "value": "14g" },
      { "nutrient": "Fiber", "value": "16g" },
      { "nutrient": "Fat", "value": "12g" }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": [
        "title_h1",
        "description_text",
        "time_stack",
        "hero_image",
        "recipe_tabs",
        "nutritional_card",
        "quick_actions_stack",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": { "text": "One-Pan Vegan Sweet Potato & Chickpea Skillet", "variant": "h1" },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": { "text": "A delicious and easy-to-make vegan skillet meal, perfect for a quick weeknight dinner." },
      "children": []
    },
    "time_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "md", "justify": "between" },
      "children": [
        "prep_time_text",
        "cook_time_text"
      ]
    },
    "prep_time_text": {
      "type": "Text",
      "props": { "text": "Prep Time: 15 min", "variant": "caption" },
      "children": []
    },
    "cook_time_text": {
      "type": "Text",
      "props": { "text": "Cook Time: 30 min", "variant": "caption" },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": { "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Sweet_Potato_and_Chickpea_Curry.jpg/1280px-Sweet_Potato_and_Chickpea_Curry.jpg", "fit": "cover" },
      "children": []
    },
    "recipe_tabs": {
      "type": "Tabs",
      "props": {
        "tabs": [
          { "title": "Ingredients", "child": "ingredients_tab_content" },
          { "title": "Instructions", "child": "instructions_tab_content" }
        ]
      },
      "children": []
    },
    "ingredients_tab_content": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md" },
      "children": [
        "ingredients_table"
      ]
    },
    "ingredients_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "ingredient", "label": "Ingredient" }
        ],
        "statePath": "/ingredients",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "instructions_tab_content": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md" },
      "children": [
        "instructions_table"
      ]
    },
    "instructions_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "step", "label": "Step" },
          { "key": "instruction", "label": "Instruction" }
        ],
        "statePath": "/instructions",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "step",
        "highlightColumns": ["instruction"]
      },
      "children": []
    },
    "nutritional_card": {
      "type": "Card",
      "props": {},
      "children": [
        "nutrition_title",
        "nutrition_table"
      ]
    },
    "nutrition_title": {
      "type": "Text",
      "props": { "text": "Nutritional Information (per serving)", "variant": "h3" },
      "children": []
    },
    "nutrition_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "nutrient", "label": "Nutrient" },
          { "key": "value", "label": "Amount" }
        ],
        "statePath": "/nutrition",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "md", "justify": "center" },
      "children": [
        "share_button",
        "save_button"
      ]
    },
    "share_button": {
      "type": "Button",
      "props": { "label": "Share Recipe" },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/share-recipe"
          }
        }
      }
    },
    "save_button": {
      "type": "Button",
      "props": { "label": "Save to Favorites", "variant": "borderless" },
      "children": [],
      "on": {
        "press": {
          "action": "setState",
          "params": {
            "path": "/isFavorite",
            "value": true
          }
        }
      }
    },
    "sources_stack": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": [
        "source_text"
      ]
    },
    "source_text": {
      "type": "Text",
      "props": { "text": "Recipe inspired by various vegan skillet recipes." },
      "children": []
    }
  }
}
